// Initialize an empty message variable.
let message = '';

// Check if Telegram Trigger node returned a message with a "text" or "caption".
try {
  const telegram = $('Telegram Trigger');
  if (telegram && telegram.item && telegram.item.json && telegram.item.json.message) {
    if (telegram.item.json.message.text) {
      message = telegram.item.json.message.text;
    } else if (telegram.item.json.message.caption) {
  message = `${telegram.item.json.message.caption} It's a real image, not just a description and you see it with your eyes now. ${$input.first().json.message}`;
}
  }
} catch (error) {
  // Telegram Trigger node might not have been executed.
}

// If no message was found from Telegram Trigger, try the OpenAI1 node.
if (!message) {
  try {
    const openai = $('OpenAI1');
    if (openai && openai.item && openai.item.json && openai.item.json.text) {
      message = openai.item.json.text;
    }
  } catch (error) {
    // OpenAI1 node might not have been executed.
  }
}

// Return the message in the expected output format.
return [{ json: { message } }];

